  "devdoc": {
    "events": {
      "AdminChanged(address,address)": {
        "details": "Emitted when the admin account has changed."
      },
      "BeaconUpgraded(address)": {
        "details": "Emitted when the beacon is changed."
      },
      "Initialized(uint8)": {
        "details": "Triggered when the contract has been initialized or reinitialized."
      },
      "Upgraded(address)": {
        "details": "Emitted when the implementation is upgraded."
      }
    },
    "kind": "dev",
    "methods": {
      "append(bytes32,string)": {
        "details": "Append a version to `genesis`'s log. The first append binds the      genesis to this Safe (and to the insertion-ordered list); later      appends only add a version. There is no edit, no replace, no delete."
      },
      "blocksOf(bytes32)": {
        "details": "The block numbers behind `history`'s timestamps, index for index:      `blocksOf(g)[i]` is the block that wrote `history(g).timestamps[i]`.      A separate call rather than a third return value of `history`, so the      existing read keeps its shape, and a reader that does not care about      blocks pays nothing for them.      `0` is a pre-upgrade entry: no block was recorded, and the timestamp      is still authoritative. Never reverts on an unknown genesis."
      },
      "constructor": {
        "custom:oz-upgrades-unsafe-allow": "constructor"
      },
      "fetch(bytes32)": {
        "details": "Latest version of `genesis`. Deliberately does **not** revert on an      unknown genesis: it returns a zeroed Entry whose `versionCount` is 0,      so a caller tests `versionCount == 0` instead of catching a revert."
      },
      "history(bytes32)": {
        "details": "All versions of `genesis`, oldest first. `timestamps` stays      `uint256[]` because that is the ABI callers already read; the      narrower stored value is widened on the way out."
      },
      "proxiableUUID()": {
        "details": "Implementation of the ERC1822 {proxiableUUID} function. This returns the storage slot used by the implementation. It is used to validate the implementation's compatibility when performing an upgrade. IMPORTANT: A proxy pointing at a proxiable contract should not be considered proxiable itself, because this risks bricking a proxy that upgrades to it, by delegating to itself until out of gas. Thus it is critical that this function revert if invoked through a proxy. This is guaranteed by the `notDelegated` modifier."
      },
      "supportsInterface(bytes4)": {
        "details": "EIP-165 role signalling. The id is a compile-time constant of the      deployed contract: it is the answer a reader discovers the role by, so      once published it may never change — a silent change makes every      already-published module undiscoverable, because no registry exists to      correct. `pure` and no storage read, so it cannot fail and cannot be      made to answer differently by an upgrade's storage."
      },
      "upgradeTo(address)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      },
      "upgradeToAndCall(address,bytes)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`, and subsequently execute the function call encoded in `data`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      }
    },
    "title": "DraftsModuleV1",
    "version": 1
  },
